        {"항목":"학개서의 핵심 구절", "내용":"자기 소위를 살펴보라는 학개서 전체를 관통하는 핵심 메시지. 삶의 열매를 통해 뿌리의 문제를 진단하는 방법", "목회적활용":"결과를 보고 원인을 찾는 영적 분별력을 가르치라"}
