        {"영어원문":"This is spoken twice, to show how necessary and important this duty of self-examination is.", "한국어번역":"이것이 두 번 말씀되었으니 자기 성찰의 의무가 얼마나 필요하고 중요한지를 보여준다.", "핵심통찰":"반복되는 명령은 그 중요성을 강조한다"}
