        {"대지":"3대지: 만군의 여호와의 명령 (하나님의 권위)", "내용":"이것은 제안이 아니라 만군의 여호와의 명령. 자기 성찰은 신앙의 필수 요소", "예화_적용":"정기적 자기 점검은 영적 건강의 핵심 습관"},
        {"대지":"결론", "내용":"오늘 잠시 멈추어 자기 소위를 살펴보자. 내 삶은 어디로 향하고 있는가. 열매는 무엇인가. 하나님이 원하시는 방향으로 가고 있는가", "예화_적용":"네비게이션이 경로를 재탐색하듯 삶의 방향을 점검하라"}
