        {"교리":"하나님의 축복과 결핍", "설명":"하나님의 축복이 없으면 인간의 노력은 헛되다. 축복의 근원이신 하나님 없이는 참된 만족이 불가능", "관련구절":"시 127:1-2, 잠 10:22, 신 8:18, 약 1:17"},
        {"교리":"채워지지 않는 욕구", "설명":"다섯 가지 결핍은 하나님 없는 삶의 근본적 공허함을 상징. 물질로는 채워지지 않는 영적 갈증", "관련구절":"전 5:10, 요 4:13-14, 사 55:1-2, 눅 12:15"}
