        {"원어":"רָצִים (라침)", "의미_문법":"빠르다/달리다 - 분사. 서두르다", "설교포인트":"자기 일에 빠르면서 하나님의 일에 느린 모순"},
        {"원어":"יַעַן מָה (야안 마)", "의미_문법":"무슨 연고냐 - 의문사. 왜냐하면", "설교포인트":"하나님이 원인을 직접 밝히신다"}
