        {"항목":"내가 불어 버렸다", "내용":"하나님이 직접 그들의 소출을 불어 버리셨다는 선언. 자연재해가 아니라 하나님의 의도적 행동", "목회적활용":"삶의 어려움 속에서 하나님의 메시지를 읽어내라"},
        {"항목":"자기 집에 빨랐음", "내용":"라침(달리다)은 급하게 서두르는 것. 자기 집 짓는 데는 급하게 달려가면서 하나님의 집은 방치한 이중적 태도", "목회적활용":"무엇에 빠른가가 우선순위를 보여준다"}
