        {"항목":"너희로 인하여", "내용":"알레켐은 '너희 위에' 또는 '너희 때문에'의 이중적 의미. 백성의 불순종이 자연 질서에까지 영향을 미침", "목회적활용":"인간의 죄가 창조 세계에 영향을 미친다는 사실을 가르치라"},
        {"항목":"언약의 저주", "내용":"하늘이 닫히고 땅이 산물을 내지 않는 것은 신명기 28:23-24의 불순종 저주의 실현", "목회적활용":"하나님의 언약에는 축복과 저주의 양면이 있음을 가르치라"}
