        {"교리":"하나님의 주권적 징계", "설명":"이슬을 그치게 하시는 것은 자연 현상이 아니라 하나님의 주권적 결정. 자연도 하나님의 명령 아래 있음", "관련구절":"신 28:23-24, 왕상 17:1, 암 4:7, 렘 14:22"},
        {"교리":"축복의 통로", "설명":"하늘의 이슬은 하나님 축복의 통로. 그 통로가 막힌 것은 관계의 단절을 의미", "관련구절":"말 3:10, 신 28:12, 창 27:28, 호 14:5"}
