        {"항목":"초막절의 의미", "내용":"초막절은 광야 생활을 기억하며 하나님의 보호를 감사하는 절기. 성전 건축 중 이 절기에 말씀이 임함은 의미심장", "목회적활용":"과거 하나님의 은혜를 기억하면 현재의 어려움을 이겨낼 수 있다"}
