        {"대지":"결론", "내용":"초막절에 하나님의 말씀이 임한 것처럼, 우리의 예배와 절기의 자리에서 하나님은 여전히 말씀하고 계신다. 낙심할 때, 지칠 때, 정확한 때에 찾아오시는 하나님을 신뢰하자", "예화_적용":"매주일 예배에 나올 때마다 하나님의 말씀을 기대하라. 하나님은 모이는 자리에서 말씀하신다"}
