        {"구절":"갈 3:28", "연결점":"유대인이나 헬라인이나 그리스도 안에서 하나", "구분":"신약"},
        {"구절":"히 13:17", "연결점":"너희를 인도하는 자들에게 순종하라", "구분":"신약"}
