    표5_매튜헨리: [
        {"영어원문":"The covenant God made with Israel when He brought them out of Egypt still stands, and His Spirit remains among them.", "한국어번역":"하나님이 이스라엘을 애굽에서 인도하실 때 맺으신 언약이 여전히 유효하고, 그의 영이 그들 가운데 머무르고 있다.", "핵심통찰":"시간이 지나도 하나님의 언약은 변하지 않는다"},
        {"영어원문":"Where the Spirit of God is, there is no reason for fear, for He is greater than all our enemies.", "한국어번역":"하나님의 영이 계신 곳에는 두려워할 이유가 없으니, 그가 우리의 모든 원수보다 크시기 때문이다.", "핵심통찰":"성령의 임재가 두려움을 몰아낸다"},
        {"영어원문":"The presence of the Spirit is better than the presence of the ark, for the Spirit is the substance of which the ark was but the shadow.", "한국어번역":"성령의 임재가 언약궤의 임재보다 낫다. 성령이 실체이고 언약궤는 그림자에 불과하기 때문이다.", "핵심통찰":"외형적 상징보다 성령의 실제 임재가 더 중요하다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"나의 영이 너희 중에 있나니 - 언약과 임재", "예화_적용":"하나님의 약속과 성령의 임재가 모든 두려움의 해답이다"},
        {"대지":"서론", "내용":"하나님은 낙심한 백성에게 두 가지를 상기시키신다. 첫째, 출애굽 때의 언약이 여전히 유효하다. 둘째, 하나님의 영이 지금도 함께 계신다. 이 두 가지면 두려워할 것이 없다", "예화_적용":"우리의 신앙은 과거의 약속과 현재의 임재 위에 서 있다"},
        {"대지":"1대지: 내가 언약한 말 (변하지 않는 약속)", "내용":"출애굽 때 맺은 언약이 수백 년이 지나도 유효함. 포로와 귀환을 거쳤지만 약속은 변하지 않았다", "예화_적용":"환경이 변해도 하나님의 약속은 변하지 않는다. 세례 때의 고백, 신앙의 약속을 기억하라"},
        {"대지":"2대지: 나의 신이 머물러 있나니 (현재의 임재)", "내용":"언약궤는 없지만 하나님의 영이 직접 함께하심. 상징보다 실체가 함께하는 것", "예화_적용":"화려한 건물이 없어도 성령이 함께하시면 그곳이 성전이다"},
        {"대지":"3대지: 두려워하지 말라 (임재의 결과)", "내용":"언약의 확인과 성령의 임재의 결론은 '두려워 말라'. 두려움은 하나님의 임재 앞에서 사라진다", "예화_적용":"두려움이 올 때 '하나님의 영이 내 안에 계시다'고 고백하라"},
        {"대지":"결론", "내용":"변하지 않는 언약과 떠나지 않는 성령. 이것이 우리 믿음의 두 기둥이다. 이 위에 서서 두려워하지 말고 하나님의 일을 계속하자", "예화_적용":"약속을 기억하고, 임재를 의식하고, 두려움을 내려놓으라. 이것이 신앙의 순서다"}
    ],
