        {"상황":"신앙이 형식적으로 느껴지는 분", "성경원리":"외형적 상징(언약궤)보다 하나님의 영의 실제 임재가 더 중요하다", "실제적용":"형식에 매이지 말고 성령의 임재를 구하라. 진정한 예배는 영과 진리로 드리는 것이다"}
