        {"대지":"서론", "내용":"성전이 가난하다고 한탄하는 백성에게 하나님의 대답은 간결하고 명쾌했다. '은도 내 것이요 금도 내 것이니라.' 모든 재물의 궁극적 소유자가 직접 성전을 짓고 계시다면, 무엇이 부족하겠는가", "예화_적용":"하나님의 사역에 재정이 부족하다고 걱정하는가? 소유자가 누구인지 기억하라"},
        {"대지":"1대지: 은도 내 것이요 (모든 재물의 소유자)", "내용":"세상의 모든 은과 금이 하나님의 것. 인간은 잠시 맡겨진 관리자에 불과", "예화_적용":"내 것이라고 생각하는 것들이 실은 모두 하나님의 것이다"},
        {"대지":"2대지: 금도 내 것이니라 (필요의 공급자)", "내용":"소유자가 필요를 아시면 공급도 하신다. 은과 금의 주인이 성전 건축에 필요한 것을 모르실 리 없다", "예화_적용":"필요를 아시는 분이 소유자이시니 걱정하지 말라"},
        {"대지":"3대지: 만군의 여호와의 말이니라 (최종 선언)", "내용":"이것은 인간의 추측이 아니라 만군의 여호와의 확정적 선언. 반박 불가능한 진리", "예화_적용":"하나님의 약속은 은행 잔고가 아니라 하나님의 신실하심에 근거한다"},
        {"대지":"결론", "내용":"하나님의 사역에 재정 걱정은 필요 없다. 은과 금의 주인이 사역을 맡기셨다면 필요한 것도 반드시 채워주신다. 우리의 몫은 신실하게 일하는 것이고, 공급은 하나님의 몫이다", "예화_적용":"관리자의 역할에 충실하라. 소유자가 책임지신다"}
