        {"상황":"하나님의 음성을 오래 듣지 못했다고 느끼는 분", "성경원리":"하나님은 두 달 후에 새로운 주제로 다시 말씀하셨다. 하나님의 말씀은 계속된다", "실제적용":"하나님의 침묵 기간은 다음 말씀의 준비 시간일 수 있다. 계속 경청하라"},
        {"상황":"새로운 시작을 앞두고 불안한 분", "성경원리":"파종기에 하나님이 말씀하신 것은 새로운 시작 전에 점검할 것을 알려주시기 위함", "실제적용":"새로운 시작 전에 하나님 앞에서 영적 상태를 점검하라. 그것이 성공의 기초다"}
