        {"대지":"3대지: 율법에 대하여 (진리의 기준)", "내용":"감정이나 경험이 아닌 율법(토라)에 근거한 판단. 하나님의 말씀이 최종 기준", "예화_적용":"삶의 판단 기준은 유행이나 감정이 아니라 하나님의 말씀이어야 한다"},
        {"대지":"결론", "내용":"하나님은 질문하는 자에게 답을 주신다. 겸손하게 물으며, 말씀에 근거하여 판단하며, 영적 지도자의 가르침을 존중하는 공동체가 건강한 교회이다", "예화_적용":"성경 공부와 질문을 두려워하지 말라. 하나님은 진리를 구하는 자에게 진리를 주신다"}
