        {"구분":"간접 접촉의 무효", "내용":"2차 접촉으로는 거룩해지지 않음", "그리스도연결":"부모의 신앙이 자녀에게 자동 전이되지 않음 - 각 개인의 믿음 필요 (요 1:13)"},
        {"구분":"제사장의 판결", "내용":"율법에 근거한 정확한 판단", "그리스도연결":"진리로 판단하시는 그리스도 (요 8:16, 계 19:11)"}
