        {"항목":"과거 회상의 목적", "내용":"성전 건축 이전의 경제적 어려움(1:6-11의 가뭄, 흉작)을 기억하게 하심. 불순종의 결과를 인식해야 순종의 복을 감사할 수 있음", "목회적활용":"과거의 어려움을 기억하는 것은 현재의 은혜를 감사하는 토대가 된다"},
        {"항목":"돌 위에 돌을 놓기 전", "내용":"성전 재건의 시작을 구체적으로 표현. 첫 돌을 놓기 전의 상태, 즉 불순종의 시기와 순종의 시기를 비교하라는 요청", "목회적활용":"순종 이전과 이후의 변화를 직접 체험하라"}
