        {"교리":"전환점의 신학", "설명":"'오늘부터'는 과거와 미래를 가르는 전환점. 순종의 시작이 복의 시작이 됨. 인생에는 결정적 전환점이 있다", "관련구절":"수 24:15, 왕상 18:21, 행 17:30, 고후 6:2"},
        {"교리":"순종과 복의 연관", "설명":"성전 건축(순종) 이전의 저주와 이후의 복을 비교하게 하시는 것은 순종과 복의 연관을 체험적으로 가르치기 위함", "관련구절":"신 28:1-14, 말 3:10, 약 1:25, 요 13:17"}
