        {"대지":"2대지: 이전을 추억하여 보라 (과거의 교훈)", "내용":"불순종의 시기를 기억하라. 고통의 원인이 무엇이었는지 돌아보라", "예화_적용":"과거의 어려움을 원망이 아닌 교훈으로 기억하라"},
        {"대지":"3대지: 돌 위에 돌을 놓기 전 (순종 이전의 상태)", "내용":"하나님의 일을 미루고 자기 일만 했던 때의 결과. 형편이 어떠했는가", "예화_적용":"하나님의 일을 뒷전에 놓았을 때의 삶을 정직하게 돌아보라"},
        {"대지":"결론", "내용":"과거를 돌아보는 것은 미래를 위한 것이다. 불순종의 과거와 순종의 현재를 비교할 때, 하나님의 역사가 선명히 보인다. 오늘이 당신의 전환점이다. 과거를 기억하되 거기 머물지 말고, 은혜의 미래를 향해 나아가자", "예화_적용":"오늘 하나님 앞에 순종을 결단하면, 오늘이 인생의 전환점이 된다"}
