        {"상황":"노력해도 결과가 안 나오는 분", "성경원리":"이십을 기대했는데 십뿐인 경험. 노력과 결과가 비례하지 않을 때가 있다", "실제적용":"결과가 안 나올 때 더 열심히 하기보다, 방향이 맞는지 먼저 점검하라"},
        {"상황":"과거의 어려움을 잊지 못하는 분", "성경원리":"하나님은 과거를 기억하되, 그 안에서 하나님의 역사를 발견하라고 하신다", "실제적용":"어려웠던 과거도 하나님의 손 안에 있었다. 그 속에서 하나님의 메시지를 찾으라"}
