        {"영어원문":"This last prophecy is directed specifically to Zerubbabel, concerning his role in God's messianic plan.", "한국어번역":"이 마지막 예언은 특별히 스룹바벨에게 향한 것으로, 하나님의 메시아적 계획에서의 그의 역할에 관한 것이다.", "핵심통찰":"하나님은 개인에게도 특별한 사명을 주신다"},
        {"영어원문":"After addressing the people's needs, God now reveals His greater plan through Zerubbabel's line.", "한국어번역":"백성의 필요를 다루신 후, 하나님은 이제 스룹바벨의 계보를 통한 더 큰 계획을 계시하신다.", "핵심통찰":"현실적 문제 해결 후 종말론적 비전이 주어진다"}
